/**
 * Represents the padding settings for each side.
 */
export interface Padding {
    /**
     * Sets the top padding in pixels.
     */
    top?: number;
    /**
     * Sets the right padding in pixels.
     */
    right?: number;
    /**
     * Sets the bottom padding in pixels.
     */
    bottom?: number;
    /**
     * Sets the left padding in pixels.
     */
    left?: number;
}
